-- ============================================================
-- AI School - FULL RESET of the finance section + import from AI_School.xlsx (v4, 2026-10-10)
-- !!! DELETES ALL finance data first: expenses (+versions, approvals, attachment records),
-- expense categories, budget lines, staff + departments, partner funding, collections and
-- manual journal entries. Users, roles, subscriptions and other modules are untouched.
-- TAKE A DB BACKUP FIRST. Safe to re-run (always rebuilds from scratch).
--
-- One invoice = one actual transfer/payment with its proof link. Each invoice line is charged
-- to its own account: salary / bonus / commission / sessions / international transfer fee.
-- Payroll of month N is transferred in month N+1 -> period_month = N (accrued at month end).
-- Expected: 59 invoices = 74121.62 SAR, funding 72942.00, collections 4640.00, 3 budget lines.
-- ============================================================
BEGIN;
DELETE FROM journal_lines;
DELETE FROM journal_entries;
DELETE FROM expense_attachments;
DELETE FROM expense_approvals;
DELETE FROM expense_versions;
DELETE FROM expenses;
DELETE FROM budget_line_categories;
DELETE FROM budget_line_approvals;
DELETE FROM budget_lines;
UPDATE staff_departments SET category_id = NULL;
DELETE FROM expense_categories WHERE parent_id IS NOT NULL;
DELETE FROM expense_categories;
DELETE FROM staff_members;
DELETE FROM staff_departments;
DELETE FROM finance_funding;
DELETE FROM finance_revenues;
DO $$
DECLARE admin_id uuid;
BEGIN
  SELECT id INTO admin_id FROM users ORDER BY created_at ASC LIMIT 1;
  IF admin_id IS NULL THEN RAISE EXCEPTION 'No user found to attribute the import to'; END IF;

  SELECT gen_random_uuid(), e.id, 1, jsonb_build_object(
      'amount', e.amount::text, 'currency', e.currency, 'expense_date', to_char(e.expense_date, 'YYYY-MM-DD'),
      'category_id', e.category_id::text, 'subcategory_id', e.subcategory_id::text, 'budget_line_id', e.budget_line_id::text,
      'staff_id', e.staff_id::text, 'description', e.description, 'vendor', e.vendor, 'invoice_number', e.invoice_number,
      'payment_method', e.payment_method, 'notes', e.notes, 'invoice_date', NULL, 'invoice_url', e.invoice_url,
      'paid_by', e.paid_by, 'period_month', e.period_month, 'breakdown', e.breakdown, 'status', e.status),
    'استيراد من ملف AI_School.xlsx', NULL, admin_id, now()
  FROM expenses e;
END $$;

-- ---------------- checks ----------------
SELECT left(coalesce(s.code, c.code), 2) || '00' AS account_group, count(*) AS lines, sum(a.amount) AS total
FROM expense_allocations a JOIN expense_categories c ON c.id = a.category_id LEFT JOIN expense_categories s ON s.id = a.subcategory_id
GROUP BY 1 ORDER BY 1;
SELECT (SELECT sum(amount) FROM expenses) AS expenses_total, 74121.62 AS expected,
       (SELECT count(*) FROM expenses) AS invoices, 59 AS expected_invoices,
       (SELECT count(*) FROM expenses WHERE invoice_url IS NOT NULL) AS with_proof_link,
       (SELECT sum(amount) FROM finance_funding) AS funding, (SELECT sum(amount) FROM finance_revenues) AS collections,
       (SELECT count(*) FROM staff_members) AS staff, (SELECT count(*) FROM budget_lines) AS budget_lines;
COMMIT;
